-- Equipment inventory number: the value printed as a barcode on the unit's label.
--  * generated by the database for every unit (any insert path), unique per hospital, 10 digits, never edited
--  * numeric on purpose: Code128 digit-only codes scan most reliably

-- 1) per-hospital counter (closed table; only the trigger function touches it) ---------------------------------------------------
create table public.equipment_number_counters (
  hospital_id uuid primary key references public.hospitals(id) on delete cascade,
  last_value  bigint not null default 0
);
alter table public.equipment_number_counters enable row level security;
revoke all on public.equipment_number_counters from anon, authenticated;

-- 2) column + backfill (oldest unit first, so numbers follow purchase order) --------------------------------------------------
alter table public.equipment add column inventory_number text;

with numbered as (
  select id, row_number() over (partition by hospital_id order by created_at, id) as n from public.equipment
)
update public.equipment e set inventory_number = lpad(numbered.n::text, 10, '0') from numbered where numbered.id = e.id;

insert into public.equipment_number_counters (hospital_id, last_value)
select hospital_id, count(*) from public.equipment group by hospital_id;

alter table public.equipment alter column inventory_number set not null;
create unique index equipment_hospital_inventory_number_uq on public.equipment (hospital_id, inventory_number);

-- 3) every new unit gets the next number; the number can never change ----------------------------------------------------------
create or replace function public._equipment_inventory_number()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_n bigint;
begin
  if tg_op = 'INSERT' then
    insert into equipment_number_counters as c (hospital_id, last_value) values (new.hospital_id, 1)
      on conflict (hospital_id) do update set last_value = c.last_value + 1
      returning c.last_value into v_n;
    new.inventory_number := lpad(v_n::text, 10, '0');
  elsif new.inventory_number is distinct from old.inventory_number then
    raise exception 'Инвентарный номер изменить нельзя';
  end if;
  return new;
end $$;

create trigger equipment_inventory_number_trg
  before insert or update of inventory_number on public.equipment
  for each row execute function public._equipment_inventory_number();

revoke execute on function public._equipment_inventory_number() from public, anon, authenticated;
